// One plucked note: 220 Hz (A3) with three harmonics, 1.2 seconds.
const rate = 44100, seconds = 1.2, freq = 220;
const samples = new Float32Array(Math.round(rate * seconds));
for (let i = 0; i < samples.length; i++) {
  const t = i / rate;
  const tone = Math.sin(2 * Math.PI * freq * t) + 0.4 * Math.sin(4 * Math.PI * freq * t) + 0.2 * Math.sin(6 * Math.PI * freq * t);
  // A fast attack, a decay, and a 5 ms fade at the end.
  samples[i] = 0.4 * tone * Math.min(1, t / 0.002) * Math.exp(-4 * t) * Math.min(1, (samples.length - 1 - i) / 220);
}

// 16-bit PCM WAV bytes from interleaved samples in [-1, 1].
function wav(samples, rate, channels) {
  const bytes = new Uint8Array(44 + samples.length * 2);
  const view = new DataView(bytes.buffer);
  const tag = (at, text) => { for (let i = 0; i < 4; i++) bytes[at + i] = text.charCodeAt(i); };
  tag(0, "RIFF"); view.setUint32(4, 36 + samples.length * 2, true); tag(8, "WAVE");
  tag(12, "fmt "); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
  view.setUint16(22, channels, true); view.setUint32(24, rate, true);
  view.setUint32(28, rate * channels * 2, true); view.setUint16(32, channels * 2, true);
  view.setUint16(34, 16, true); tag(36, "data"); view.setUint32(40, samples.length * 2, true);
  samples.forEach((s, i) => view.setInt16(44 + i * 2, Math.round(Math.max(-1, Math.min(1, s)) * 32767), true));
  return bytes;
}

await output("audio", await media.toAudio(wav(samples, rate, 1), { mimeType: "audio/wav", filename: "note.wav" }));
